//! `MEMORY.md` — the working memory every audit starts from (spec §B.9).
//!
//! Generated by the system from already-loaded data; never edited by the AI. Structure and
//! system lines are English (AI input); free text from the owner or from AI outputs is
//! kept as written. Deterministic: same input, same output.

use std::collections::BTreeMap;
use std::fmt::Write as _;

use opentatu_core::{App, Audit, CoverageSummary, SecurityMap, Timestamp};

/// Audits listed one by one in the timeline; older ones are summarized per month.
const TIMELINE_LIMIT: usize = 10;

/// Months of older audits summarized (keeps the file within ~2,000 tokens).
const MONTH_SUMMARY_LIMIT: usize = 12;

/// Everything `MEMORY.md` is built from.
#[derive(Debug, Clone, Copy)]
pub struct MemoryInput<'a> {
    /// The app.
    pub app: &'a App,
    /// Generation time (from the clock, R03).
    pub updated_at: &'a Timestamp,
    /// The app's audits, newest first.
    pub audits: &'a [Audit],
    /// Contents of `OWNER-NOTES.md`, if any.
    pub owner_notes: Option<&'a str>,
    /// Latest security map, if any.
    pub map: Option<&'a SecurityMap>,
    /// ASVS coverage of the latest audit that produced a map, if any.
    pub coverage: Option<&'a CoverageSummary>,
}

/// Renders `MEMORY.md`.
pub fn render_memory(input: &MemoryInput<'_>) -> String {
    let profile = &input.app.profile;
    let mut out = String::new();
    let _ = writeln!(out, "# Memory — {} ({})", profile.name, profile.slug);
    let _ = writeln!(out, "Updated at: {}", input.updated_at.iso());
    match input.audits.first() {
        Some(last) => {
            let _ = writeln!(
                out,
                "Last audit: {} ({}, {})",
                last.id, last.kind, last.status
            );
        }
        None => out.push_str("Last audit: none\n"),
    }

    out.push_str("\n## Profile\n");
    let _ = writeln!(
        out,
        "Repository: {} (branch {})",
        profile.repo_url, profile.branch
    );
    let _ = writeln!(out, "Stack: {}.", list_or(&profile.stack, "unknown"));
    let _ = writeln!(
        out,
        "Sensitive data: {}.",
        list_or(&profile.sensitive_data, "none declared")
    );
    let _ = writeln!(
        out,
        "Lab: {}.",
        profile
            .lab_url
            .as_deref()
            .unwrap_or("none (static analysis only)")
    );
    match input.map {
        Some(map) => {
            let _ = writeln!(
                out,
                "Mapped entry points: {}. External integrations: {}. Map: {} (commit {}).",
                map.content.entry_points.len(),
                map.content.integrations.len(),
                map.map_id,
                map.commit.short()
            );
        }
        None => out.push_str("Mapped entry points: no map yet.\n"),
    }

    out.push_str("\n## Current situation\n");
    out.push_str("Open findings: none recorded yet.\n");
    out.push_str("Tasks awaiting a fix: 0. Awaiting reverification: 0.\n");
    match input.coverage {
        Some(coverage) => {
            let _ = writeln!(
                out,
                "ASVS coverage: {}% ({} of {} applicable requirements verified; {} failed, {} not tested).",
                coverage.percent,
                coverage.verified,
                coverage.applicable_requirements,
                coverage.failed,
                coverage.not_tested
            );
        }
        None => out.push_str("ASVS coverage: not measured yet.\n"),
    }

    out.push_str("\n## Timeline (last 10 audits)\n");
    if input.audits.is_empty() {
        out.push_str("- No audits yet.\n");
    }
    for audit in input.audits.iter().take(TIMELINE_LIMIT) {
        let _ = writeln!(
            out,
            "- {} — {} — {} — {} — commit {}",
            audit.created_at.local_minute(),
            audit.id,
            audit.kind,
            audit.status,
            audit.commit.short()
        );
    }
    let mut older: BTreeMap<String, usize> = BTreeMap::new();
    for audit in input.audits.iter().skip(TIMELINE_LIMIT) {
        *older.entry(audit.created_at.local_month()).or_default() += 1;
    }
    for (month, count) in older.iter().rev().take(MONTH_SUMMARY_LIMIT) {
        let _ = writeln!(out, "- {month}: {count} older audit(s)");
    }

    out.push_str("\n## Open findings (summary)\n- None recorded yet.\n");
    out.push_str("\n## Known false positives (do not reopen without code changes)\n- None.\n");
    out.push_str("\n## Accepted risks\n- None.\n");

    out.push_str("\n## Poorly covered areas / pending investigations\n");
    match input.audits.first() {
        Some(last) if !last.limitations.is_empty() => {
            for limitation in &last.limitations {
                let _ = writeln!(out, "- {limitation}");
            }
        }
        Some(_) => out.push_str("- None reported by the last audit.\n"),
        None => out.push_str("- Everything: no audit has run yet.\n"),
    }

    out.push_str("\n## Owner notes\n");
    match input
        .owner_notes
        .map(str::trim)
        .filter(|notes| !notes.is_empty())
    {
        Some(notes) => {
            out.push_str(notes);
            out.push('\n');
        }
        None => out.push_str("(none — the owner may write them in OWNER-NOTES.md)\n"),
    }
    out
}

fn list_or(values: &[String], fallback: &str) -> String {
    if values.is_empty() {
        fallback.to_owned()
    } else {
        values.join(", ")
    }
}

#[cfg(test)]
mod tests {
    use opentatu_core::{AuditKind, AuditStatus, NewApp, Slug};

    use super::*;

    fn app() -> App {
        App {
            profile: NewApp {
                slug: Slug::new("abastevo").unwrap(),
                name: "Abastevo".into(),
                repo_url: "git@github.com:owner/abastevo.git".into(),
                branch: "main".into(),
                stack: vec!["Next.js".into(), "Postgres".into()],
                sensitive_data: vec!["dados pessoais de clientes".into()],
                lab_url: None,
            },
            created_at: "2026-11-01T09:00:00-03:00".parse().unwrap(),
        }
    }

    fn audit(created: &str, minute: &str) -> Audit {
        let at: Timestamp = created.parse().unwrap();
        Audit {
            id: format!("AUD-ABASTEVO-{minute}").parse().unwrap(),
            app: Slug::new("abastevo").unwrap(),
            kind: AuditKind::Full,
            status: AuditStatus::Partial,
            commit: "4c4a5df92ace8d8068e57362a7308e8b9d031b3a".parse().unwrap(),
            branch: Some("main".into()),
            previous_audit_id: None,
            created_at: at,
            started_at: Some(at),
            completed_at: Some(at),
            checkpoint: None,
            limitations: vec!["Scanners estáticos ainda não executados.".into()],
        }
    }

    #[test]
    fn renders_spec_b9_sections() {
        let audits = [audit("2026-11-12T09:00:00-03:00", "20261112-0900")];
        let updated: Timestamp = "2026-11-12T09:01:00-03:00".parse().unwrap();
        let memory = render_memory(&MemoryInput {
            app: &app(),
            updated_at: &updated,
            audits: &audits,
            owner_notes: Some("Webhook de pagamento é crítico."),
            map: None,
            coverage: Some(&CoverageSummary {
                applicable_requirements: 128,
                verified: 82,
                failed: 3,
                not_tested: 43,
                percent: 64,
            }),
        });
        for section in [
            "# Memory — Abastevo (abastevo)",
            "Last audit: AUD-ABASTEVO-20261112-0900 (FULL, PARTIAL)",
            "## Timeline (last 10 audits)",
            "- 2026-11-12 09:00 — AUD-ABASTEVO-20261112-0900 — FULL — PARTIAL — commit 4c4a5df92ace",
            "- Scanners estáticos ainda não executados.",
            "Webhook de pagamento é crítico.",
            "Mapped entry points: no map yet.",
            "ASVS coverage: 64% (82 of 128 applicable requirements verified; 3 failed, 43 not tested).",
        ] {
            assert!(
                memory.contains(section),
                "missing {section:?} in:\n{memory}"
            );
        }
    }

    #[test]
    fn old_audits_are_summarized_per_month_and_output_is_small() {
        let audits: Vec<Audit> = (0..30)
            .map(|day| {
                let month = if day < 15 { 11 } else { 10 };
                let dd = 28 - (day % 15);
                audit(
                    &format!("2026-{month:02}-{dd:02}T09:00:00-03:00"),
                    &format!("2026{month:02}{dd:02}-0900"),
                )
            })
            .collect();
        let updated: Timestamp = "2026-11-30T09:00:00-03:00".parse().unwrap();
        let memory = render_memory(&MemoryInput {
            app: &app(),
            updated_at: &updated,
            audits: &audits,
            owner_notes: None,
            map: None,
            coverage: None,
        });
        assert!(memory.contains("- 2026-11: 5 older audit(s)"), "{memory}");
        assert!(memory.contains("- 2026-10: 15 older audit(s)"), "{memory}");
        assert!(
            memory.len() < 8_000,
            "MEMORY.md must stay near 2,000 tokens"
        );
    }

    #[test]
    fn empty_history_is_explicit() {
        let updated: Timestamp = "2026-11-12T09:00:00-03:00".parse().unwrap();
        let memory = render_memory(&MemoryInput {
            app: &app(),
            updated_at: &updated,
            audits: &[],
            owner_notes: None,
            map: None,
            coverage: None,
        });
        assert!(memory.contains("Last audit: none"));
        assert!(memory.contains("- Everything: no audit has run yet."));
    }
}
